```perl
#!/usr/bin/env perl
use strict;
use warnings;
use utf8;

use FindBin;
use lib "$FindBin::Bin";   # so Palindrome.pm can be found where it sits
use Palindrome;

my $input = shift @ARGV;

if (!defined $input) {
    die "Usage: $0 <string>\nInput string not provided.\n";
}

my $normalized = Palindrome::normalize($input);

if (!defined $normalized) {
    die "Input validation failed: $normalized\n";
}

my $result = Palindrome::is_palindrome($normalized);

if ($result->{is_palindrome}) {
    print "The input is a palindrome.\n";
} else {
    print "The input is NOT a palindrome.\n";
}

print "Original:   $input\n";
print "Normalized: $result->{normalized}\n";
print "Reads the same backwards: ", $result->{reversed}, "\n";
